AR_D = str.maketrans('0123456789', '٠١٢٣٤٥٦٧٨٩')
def an(n): return str(n).translate(AR_D)
def LINK(n, label=None):
    return f'<a href="#s{n}">{label or ("الباب " + an(n))}</a>'

def tbl(rows, heads, anchor=None):
    h = ''.join(f'<th>{x}</th>' for x in heads)
    body = []
    for r in rows:
        cells = []
        for c in r:
            if isinstance(c, tuple):
                cells.append(f'<td class="{c[1]}">{c[0]}</td>')
            else:
                cells.append(f'<td>{c}</td>')
        body.append('<tr>' + ''.join(cells) + '</tr>')
    return (f'<div class="tblwrap" id="{anchor}"><table><thead><tr>{h}</tr></thead>'
            '<tbody>\n' + '\n'.join(body) + '\n</tbody></table></div>')

